import{_ as t,o as r,c as n,ag as a}from"./chunks/framework.DqVSm8kp.js";const o="/llmxray/docs/educators/fr/token-pipeline.svg",s="/llmxray/docs/educators/fr/bpe-process.svg",i="/llmxray/docs/educators/fr/strawberry-tokenization.svg",l="/llmxray/docs/educators/fr/language-bias.svg",f=JSON.parse(`{"title":"Module 1 : Qu'est-ce qu'un token ?","description":"","frontmatter":{},"headers":[],"relativePath":"fr/community/educators/module-1.md","filePath":"fr/community/educators/module-1.md"}`),u={name:"fr/community/educators/module-1.md"};function d(c,e,p,m,h,g){return r(),n("div",null,[...e[0]||(e[0]=[a('<h1 id="module-1-qu-est-ce-qu-un-token" tabindex="-1">Module 1 : Qu&#39;est-ce qu&#39;un token ? <a class="header-anchor" href="#module-1-qu-est-ce-qu-un-token" aria-label="Permalink to &quot;Module 1 : Qu&#39;est-ce qu&#39;un token ?&quot;">​</a></h1><div style="background:linear-gradient(135deg, rgba(168,85,247,0.08), rgba(124,58,237,0.04));border-left:4px solid #a855f7;padding:1rem 1.5rem;border-radius:0 8px 8px 0;margin-bottom:2rem;"><p><strong>L&#39;Observateur</strong> — Voir l&#39;invisible</p><p><strong>Durée :</strong> 45 min | <strong>Difficulté :</strong> Débutant | <strong>Prérequis :</strong> Aucun</p></div><h2 id="le-moment-eureka" tabindex="-1">Le Moment Eureka <a class="header-anchor" href="#le-moment-eureka" aria-label="Permalink to &quot;Le Moment Eureka&quot;">​</a></h2><blockquote><p>L&#39;IA ne pense pas en mots. Elle pense en tokens. Et les tokens ne sont pas ce que vous imaginez.</p></blockquote><p>C&#39;est l&#39;intuition fondamentale qui change tout dans la compréhension des modèles de langage par les étudiants. Chaque concept qui suit — température, fenêtres de contexte, embeddings, tool calling — repose sur la compréhension de ce que sont réellement les tokens.</p><p><img src="'+o+'" alt="Du Texte au Token à la Prédiction"></p><hr><h2 id="contexte-conceptuel" tabindex="-1">Contexte Conceptuel <a class="header-anchor" href="#contexte-conceptuel" aria-label="Permalink to &quot;Contexte Conceptuel&quot;">​</a></h2><h3 id="qu-est-ce-qu-un-token" tabindex="-1">Qu&#39;est-ce qu&#39;un token ? <a class="header-anchor" href="#qu-est-ce-qu-un-token" aria-label="Permalink to &quot;Qu&#39;est-ce qu&#39;un token ?&quot;">​</a></h3><p>Un <strong>token</strong> est la plus petite unité de texte traitée par un modèle de langage. Les tokens ne sont ni des mots, ni des caractères, ni des syllabes — ce sont des <strong>unités sous-lexicales</strong> déterminées par un algorithme statistique entraîné sur un large corpus.</p><p>L&#39;algorithme dominant est le <strong>Byte-Pair Encoding (BPE)</strong>, introduit en NLP par Sennrich et al. (2016). Le BPE commence par les caractères individuels et fusionne itérativement les paires adjacentes les plus fréquentes jusqu&#39;à atteindre une taille de vocabulaire cible (généralement 32 000 à 128 000 tokens).</p><p>Par exemple, le mot &quot;understanding&quot; pourrait être tokenisé ainsi :</p><ul><li><code>[&quot;under&quot;, &quot;stand&quot;, &quot;ing&quot;]</code> (3 tokens)</li></ul><p>Tandis que &quot;AI&quot; pourrait donner :</p><ul><li><code>[&quot;AI&quot;]</code> (1 token — suffisamment courant pour constituer une entrée unique)</li></ul><h3 id="pourquoi-la-tokenisation-est-elle-importante" tabindex="-1">Pourquoi la tokenisation est-elle importante ? <a class="header-anchor" href="#pourquoi-la-tokenisation-est-elle-importante" aria-label="Permalink to &quot;Pourquoi la tokenisation est-elle importante ?&quot;">​</a></h3><p>Chaque aspect du comportement des LLM se mesure en tokens :</p><table tabindex="0"><thead><tr><th>Aspect</th><th>Impact des tokens</th></tr></thead><tbody><tr><td><strong>Coût</strong></td><td>La tarification des API se fait au token</td></tr><tr><td><strong>Vitesse</strong></td><td>Les modèles génèrent un token par étape d&#39;inférence</td></tr><tr><td><strong>Fenêtre de contexte</strong></td><td>Le nombre maximum de tokens que le modèle peut voir en une fois</td></tr><tr><td><strong>Qualité</strong></td><td>Les frontières de tokens affectent ce que le modèle peut &quot;voir&quot; à l&#39;intérieur d&#39;un mot</td></tr><tr><td><strong>Équité</strong></td><td>Les langues ayant moins de tokens dans le vocabulaire nécessitent plus de tokens par phrase</td></tr></tbody></table><h3 id="comment-fonctionne-le-bpe-simplifie" tabindex="-1">Comment fonctionne le BPE (simplifié) <a class="header-anchor" href="#comment-fonctionne-le-bpe-simplifie" aria-label="Permalink to &quot;Comment fonctionne le BPE (simplifié)&quot;">​</a></h3><ol><li>Commencer avec tous les octets individuels (256 tokens de base)</li><li>Compter toutes les paires adjacentes dans le corpus d&#39;entraînement</li><li>Fusionner la paire la plus fréquente en un nouveau token</li><li>Répéter jusqu&#39;à atteindre la taille de vocabulaire cible</li></ol><p>Cela signifie :</p><ul><li>Les mots courants deviennent des tokens uniques : <code>&quot;the&quot;</code>, <code>&quot;and&quot;</code>, <code>&quot;is&quot;</code></li><li>Les mots rares sont décomposés en morceaux : <code>&quot;tokenization&quot;</code> → <code>[&quot;token&quot;, &quot;ization&quot;]</code></li><li>Les mots très rares sont réduits à des caractères individuels</li></ul><p>La famille LLaMA 3 utilise un tokenizer BPE avec un vocabulaire de 128 000 tokens, entraîné principalement sur du texte anglais (Grattafiori et al., 2024).</p><p><img src="'+s+'" alt="Comment fonctionne la tokenisation BPE"></p><hr><h2 id="exercices-pratiques" tabindex="-1">Exercices Pratiques <a class="header-anchor" href="#exercices-pratiques" aria-label="Permalink to &quot;Exercices Pratiques&quot;">​</a></h2><h3 id="exercice-1-voir-les-tokens-arriver-en-temps-reel" tabindex="-1">Exercice 1 : Voir les tokens arriver en temps réel <a class="header-anchor" href="#exercice-1-voir-les-tokens-arriver-en-temps-reel" aria-label="Permalink to &quot;Exercice 1 : Voir les tokens arriver en temps réel&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Ouvrez <strong>Chat Diagnostics</strong> dans LLMxRay et sélectionnez un modèle (ex. <code>llama3.2</code>)</li><li>Envoyez : <em>&quot;Explain what gravity is in one sentence&quot;</em></li><li>Observez les tokens arriver un par un — chaque token apparaît au fur et à mesure que le modèle le produit</li><li>Ouvrez l&#39;onglet <strong>Stream</strong> — voyez chaque token avec son horodatage et sa latence inter-token</li><li>Remarquez la <strong>coloration de confiance</strong> : les tokens verts sont arrivés rapidement (confiance élevée), les tokens orange/rouges sont arrivés lentement (confiance plus faible)</li></ol><p><strong>Ce qu&#39;il faut observer :</strong></p><ul><li>Les tokens ne sont pas toujours des mots complets. Vous verrez des mots partiels, de la ponctuation et des espaces comme tokens séparés.</li><li>Certains tokens arrivent presque instantanément (le modèle était très certain). D&#39;autres prennent plus de temps (le modèle &quot;choisissait&quot; entre plusieurs options).</li><li>Le premier token prend le plus de temps (Time to First Token / TTFT) — c&#39;est le moment où le modèle traite l&#39;intégralité de votre prompt.</li></ul><div class="info custom-block"><p class="custom-block-title">Qu&#39;est-ce que la coloration de confiance ?</p><p>LLMxRay estime la confiance des tokens à partir de la <strong>latence inter-token</strong>. Une génération plus rapide suggère que le modèle avait une prédiction dominante pour le token suivant. C&#39;est une approximation pratique — pour une mesure de confiance mathématiquement précise, la fonctionnalité Benchmark utilise de vrais logprobs via l&#39;endpoint compatible OpenAI. Voir le Module 3 pour l&#39;histoire complète sur la confiance et la vérité.</p></div><hr><h3 id="exercice-2-le-choc-du-tokenizer" tabindex="-1">Exercice 2 : Le choc du tokenizer <a class="header-anchor" href="#exercice-2-le-choc-du-tokenizer" aria-label="Permalink to &quot;Exercice 2 : Le choc du tokenizer&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Dans le chat, demandez : <em>&quot;Count the letters in the word &#39;strawberry&#39;&quot;</em></li><li>Le modèle dira probablement 10 — mais <code>strawberry</code> contient 10 lettres dont 3 r. Beaucoup de modèles comptent 2 r au lieu de 3.</li><li>Maintenant demandez : <em>&quot;How many words are in this sentence: The quick brown fox jumps over the lazy dog&quot;</em></li><li>Le modèle répond correctement (9 mots) — compter les mots est plus facile que compter les lettres</li></ol><p><strong>Pourquoi cela se produit :</strong></p><p>Le mot <code>strawberry</code> est tokenisé en quelque chose comme <code>[&quot;str&quot;, &quot;aw&quot;, &quot;berry&quot;]</code> — le modèle ne voit jamais les lettres individuelles. Il traite ces morceaux comme des unités atomiques. Compter les lettres nécessite un raisonnement au niveau des caractères, mais le modèle opère au niveau des tokens.</p><p>Ce n&#39;est pas un bug — c&#39;est une conséquence fondamentale de la tokenisation sous-lexicale. Le modèle ne peut littéralement pas &quot;voir&quot; les lettres individuelles à l&#39;intérieur d&#39;un token.</p><p><img src="'+i+'" alt="Pourquoi les LLMs ne peuvent pas compter les lettres dans Strawberry"></p><div class="tip custom-block"><p class="custom-block-title">Essayez par vous-même</p><p>Visitez le <a href="https://tiktokenizer.vercel.app/" target="_blank" rel="noreferrer">playground Tiktokenizer</a> ou le <a href="https://huggingface.co/spaces/Xenova/the-tokenizer-playground" target="_blank" rel="noreferrer">HuggingFace Tokenizer Playground</a> pour visualiser comment différents modèles tokenisent le même texte. Comparez comment <code>llama</code> et <code>gpt-4</code> tokenisent <code>&quot;strawberry&quot;</code> — ils peuvent le découper différemment.</p></div><p><strong>Contexte de recherche :</strong> Fu et al. (2024) ont mené une étude systématique de ce phénomène dans leur article <em>&quot;Why Do Large Language Models Struggle to Count Letters?&quot;</em> Ils ont découvert que les erreurs corrèlent fortement avec la fréquence des lettres et la longueur des mots, et non avec la fréquence d&#39;apparition du mot dans les données d&#39;entraînement — confirmant que la limitation est architecturale (tokenisation), et non un manque de connaissances.</p><hr><h3 id="exercice-3-le-biais-linguistique-de-la-tokenisation" tabindex="-1">Exercice 3 : Le biais linguistique de la tokenisation <a class="header-anchor" href="#exercice-3-le-biais-linguistique-de-la-tokenisation" aria-label="Permalink to &quot;Exercice 3 : Le biais linguistique de la tokenisation&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Envoyez ce prompt au modèle : <em>&quot;Say hello in one sentence&quot;</em></li><li>Ouvrez l&#39;onglet <strong>Stream</strong> et comptez les tokens dans la réponse</li><li>Maintenant envoyez : <em>&quot;Dis bonjour en une phrase&quot;</em> (la même demande en français)</li><li>Comptez à nouveau les tokens — la réponse en français utilisera probablement plus de tokens</li><li>Essayez la même chose en allemand, espagnol, chinois, arabe ou toute autre langue que vous connaissez</li><li>Notez le nombre de tokens pour chaque langue</li></ol><p><strong>Ce que vous allez découvrir :</strong></p><p>Le même contenu sémantique nécessite <strong>significativement plus de tokens</strong> dans les langues autres que l&#39;anglais. Ce n&#39;est pas parce que le français est &quot;plus complexe&quot; — c&#39;est parce que le vocabulaire du tokenizer a été construit principalement à partir de texte anglais.</p><table tabindex="0"><thead><tr><th>Langue</th><th>Ratio typique de tokens par rapport à l&#39;anglais</th></tr></thead><tbody><tr><td>Anglais</td><td>1,0x (référence)</td></tr><tr><td>Français</td><td>1,3-1,5x</td></tr><tr><td>Allemand</td><td>1,4-1,6x</td></tr><tr><td>Chinois</td><td>1,5-2,0x</td></tr><tr><td>Arabe</td><td>2,0-3,0x</td></tr><tr><td>Certaines langues africaines</td><td>Jusqu&#39;à 5-15x</td></tr></tbody></table><p><img src="'+l+'" alt="Biais linguistique des tokenizers"></p><p><strong>Pourquoi c&#39;est important en pratique :</strong></p><ul><li>Un utilisateur francophone atteint la limite de la fenêtre de contexte <strong>30 à 50 % plus tôt</strong> qu&#39;un utilisateur anglophone</li><li>Les coûts d&#39;API sont <strong>proportionnellement plus élevés</strong> pour les langues non anglophones</li><li>La génération est <strong>plus lente</strong> (plus de tokens à produire pour le même contenu)</li><li>La qualité peut se dégrader parce que le modèle dispose de moins de &quot;tokens de réflexion&quot;</li></ul><div class="warning custom-block"><p class="custom-block-title">Ceci est un domaine de recherche actif</p><p>Petrov et al. (2023) ont montré dans leur article NeurIPS <em>&quot;Language Model Tokenizers Introduce Unfairness Between Languages&quot;</em> que le même texte peut nécessiter jusqu&#39;à <strong>15x plus de tokens</strong> dans certaines langues par rapport à l&#39;anglais, sur 17 tokenizers différents. Ce n&#39;est pas seulement une préoccupation théorique — cela a des implications réelles en termes de coût, de latence et de qualité.</p><p>Explorez leur <a href="https://aleksandarpetrov.github.io/tokenization-fairness/" target="_blank" rel="noreferrer">démo interactive</a> pour visualiser la disparité entre les langues.</p></div><hr><h3 id="exercice-4-vitesse-et-confiance" tabindex="-1">Exercice 4 : Vitesse et confiance <a class="header-anchor" href="#exercice-4-vitesse-et-confiance" aria-label="Permalink to &quot;Exercice 4 : Vitesse et confiance&quot;">​</a></h3><p><strong>Ce qu&#39;il faut faire :</strong></p><ol><li>Menez plusieurs conversations avec le modèle sur différents sujets</li><li>Pour chaque réponse, observez la coloration de confiance dans le flux de tokens</li><li>Remarquez les schémas récurrents : <ul><li>Phrases courantes (&quot;I think&quot;, &quot;The answer is&quot;) → vert (rapide, confiant)</li><li>Termes techniques, chiffres, noms propres → plus orange (plus lent, moins certain)</li><li>Formulations créatives ou inhabituelles → orange/rouge majoritaire (le plus lent, le moins certain)</li></ul></li><li>Ouvrez deux onglets Stream côte à côte (de sessions différentes) et comparez les distributions de latence</li></ol><p><strong>Matière à réflexion :</strong></p><ul><li>La vitesse (latence inter-token) est un <strong>indicateur indirect</strong> de la confiance, pas une mesure directe</li><li>Le modèle génère les continuations &quot;évidentes&quot; plus rapidement que les continuations surprenantes</li><li>Cela reflète le fonctionnement de la distribution de probabilité softmax : lorsqu&#39;un token a une probabilité nettement supérieure aux alternatives, le calcul converge plus rapidement</li><li>Pour une mesure de confiance <strong>précise</strong>, il faut les logprobs réels — que LLMxRay fournit via la fonctionnalité Benchmark (Module 3)</li></ul><hr><h2 id="points-cles" tabindex="-1">Points Clés <a class="header-anchor" href="#points-cles" aria-label="Permalink to &quot;Points Clés&quot;">​</a></h2><ol><li><strong>Les tokens sont l&#39;unité atomique</strong> du calcul des LLM — ni les mots, ni les caractères</li><li><strong>La tokenisation BPE</strong> crée un vocabulaire à partir de schémas statistiques, pas de règles linguistiques</li><li><strong>Les frontières de tokens</strong> déterminent ce sur quoi le modèle peut ou ne peut pas raisonner (comptage de lettres, manipulation de caractères)</li><li><strong>Le biais linguistique</strong> des tokenizers crée une inégalité mesurable en termes de coût, vitesse et qualité entre les langues</li><li><strong>La vitesse corrèle avec la confiance</strong> mais n&#39;est pas identique — c&#39;est une approximation utile</li></ol><hr><h2 id="questions-de-discussion" tabindex="-1">Questions de Discussion <a class="header-anchor" href="#questions-de-discussion" aria-label="Permalink to &quot;Questions de Discussion&quot;">​</a></h2><p>Pour une discussion en classe ou en séminaire :</p><ol><li>Si les tokenizers sont entraînés sur des corpus à dominante anglophone, à quoi ressemblerait un tokenizer multilingue &quot;équitable&quot; ? Est-ce même possible avec une taille de vocabulaire fixe ?</li><li>Le problème du &quot;strawberry&quot; montre que les modèles ne peuvent pas raisonner sur les caractères à l&#39;intérieur des tokens. Quelles autres tâches apparemment simples pourraient être affectées par les frontières de tokens ?</li><li>Les entreprises d&#39;IA devraient-elles divulguer le biais linguistique de leur tokenizer ? Comment cela changerait-il la façon dont les utilisateurs non anglophones interagissent avec l&#39;IA ?</li><li>Si vous deviez concevoir un tokenizer pour un domaine spécifique (médical, juridique, code), comment modifieriez-vous le processus d&#39;entraînement ?</li></ol><hr><h2 id="lectures-complementaires" tabindex="-1">Lectures Complémentaires <a class="header-anchor" href="#lectures-complementaires" aria-label="Permalink to &quot;Lectures Complémentaires&quot;">​</a></h2><h3 id="articles-academiques" tabindex="-1">Articles académiques <a class="header-anchor" href="#articles-academiques" aria-label="Permalink to &quot;Articles académiques&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Article</th><th>Auteurs</th><th>Année</th><th>Lien</th></tr></thead><tbody><tr><td>Neural Machine Translation of Rare Words with Subword Units</td><td>Sennrich, Haddow, Birch</td><td>2016</td><td><a href="https://arxiv.org/abs/1508.07909" target="_blank" rel="noreferrer">arXiv:1508.07909</a></td></tr><tr><td>SentencePiece: A simple and language independent subword tokenizer</td><td>Kudo, Richardson</td><td>2018</td><td><a href="https://arxiv.org/abs/1808.06226" target="_blank" rel="noreferrer">arXiv:1808.06226</a></td></tr><tr><td>Language Model Tokenizers Introduce Unfairness Between Languages</td><td>Petrov, La Malfa, Torr, Bibi</td><td>2023</td><td><a href="https://arxiv.org/abs/2305.15425" target="_blank" rel="noreferrer">arXiv:2305.15425</a></td></tr><tr><td>Why Do Large Language Models Struggle to Count Letters?</td><td>Fu, Ferrando, Conde, Arriaga, Reviriego</td><td>2024</td><td><a href="https://arxiv.org/abs/2412.18626" target="_blank" rel="noreferrer">arXiv:2412.18626</a></td></tr><tr><td>Attention Is All You Need</td><td>Vaswani et al.</td><td>2017</td><td><a href="https://arxiv.org/abs/1706.03762" target="_blank" rel="noreferrer">arXiv:1706.03762</a></td></tr><tr><td>The Llama 3 Herd of Models</td><td>Grattafiori et al. (Meta AI)</td><td>2024</td><td><a href="https://arxiv.org/abs/2407.21783" target="_blank" rel="noreferrer">arXiv:2407.21783</a></td></tr></tbody></table><h3 id="tutoriels-et-explications-visuelles" tabindex="-1">Tutoriels et explications visuelles <a class="header-anchor" href="#tutoriels-et-explications-visuelles" aria-label="Permalink to &quot;Tutoriels et explications visuelles&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Ressource</th><th>Auteur</th><th>Lien</th></tr></thead><tbody><tr><td>Let&#39;s build the GPT Tokenizer (video, 2h13m)</td><td>Andrej Karpathy</td><td><a href="https://www.youtube.com/watch?v=zduSFxRajkE" target="_blank" rel="noreferrer">YouTube</a></td></tr><tr><td>The Illustrated Transformer</td><td>Jay Alammar</td><td><a href="https://jalammar.github.io/illustrated-transformer/" target="_blank" rel="noreferrer">jalammar.github.io</a></td></tr><tr><td>HuggingFace NLP Course, Chapter 6: Tokenizers</td><td>Hugging Face</td><td><a href="https://huggingface.co/learn/llm-course/en/chapter6/5" target="_blank" rel="noreferrer">huggingface.co/learn</a></td></tr><tr><td>LLM Sampling Parameters Explained</td><td>Let&#39;s Data Science</td><td><a href="https://letsdatascience.com/blog/llm-sampling-temperature-top-k-top-p-and-min-p-explained" target="_blank" rel="noreferrer">letsdatascience.com</a></td></tr></tbody></table><h3 id="outils-interactifs" tabindex="-1">Outils interactifs <a class="header-anchor" href="#outils-interactifs" aria-label="Permalink to &quot;Outils interactifs&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Outil</th><th>Lien</th><th>Description</th></tr></thead><tbody><tr><td>Tiktokenizer</td><td><a href="https://tiktokenizer.vercel.app/" target="_blank" rel="noreferrer">tiktokenizer.vercel.app</a></td><td>Visualiser la tokenisation GPT avec un code couleur</td></tr><tr><td>HuggingFace Tokenizer Playground</td><td><a href="https://huggingface.co/spaces/Xenova/the-tokenizer-playground" target="_blank" rel="noreferrer">huggingface.co/spaces/Xenova</a></td><td>Comparer la tokenisation entre modèles ouverts (LLaMA, Mistral, etc.)</td></tr><tr><td>OpenAI Tokenizer</td><td><a href="https://platform.openai.com/tokenizer" target="_blank" rel="noreferrer">platform.openai.com/tokenizer</a></td><td>Visualiseur officiel de tokens OpenAI</td></tr></tbody></table><h3 id="cours-universitaires-associes" tabindex="-1">Cours universitaires associés <a class="header-anchor" href="#cours-universitaires-associes" aria-label="Permalink to &quot;Cours universitaires associés&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Cours</th><th>Institution</th><th>Lien</th></tr></thead><tbody><tr><td>CS224N: NLP with Deep Learning</td><td>Stanford</td><td><a href="https://web.stanford.edu/class/cs224n/" target="_blank" rel="noreferrer">web.stanford.edu/class/cs224n</a></td></tr><tr><td>11-711: Advanced NLP</td><td>CMU</td><td><a href="https://www.phontron.com/class/anlp2024/" target="_blank" rel="noreferrer">phontron.com/class/anlp2024</a></td></tr></tbody></table><hr><h2 id="evaluation" tabindex="-1">Évaluation <a class="header-anchor" href="#evaluation" aria-label="Permalink to &quot;Évaluation&quot;">​</a></h2><p><strong>Option A — Réflexion écrite (individuel, 300 mots) :</strong> Décrivez un élément de la tokenisation qui vous a surpris, en vous appuyant sur vos expériences dans LLMxRay (incluez des captures d&#39;écran).</p><p><strong>Option B — Analyse de données (individuel ou en binôme, 1 page) :</strong> Tokenisez le même paragraphe dans 4 langues ou plus à l&#39;aide du HuggingFace Tokenizer Playground. Présentez un tableau des nombres de tokens, calculez les ratios par rapport à l&#39;anglais et discutez des implications en termes d&#39;équité.</p><p><strong>Option C — Présentation (groupes de 2-3, 5 minutes) :</strong> Concevez et présentez un &quot;défi de tokenisation&quot; — une tâche que les LLM devraient pouvoir accomplir mais ne peuvent pas à cause des frontières de tokens. Faites-en la démonstration en direct dans LLMxRay et expliquez pourquoi le tokenizer est le goulot d&#39;étranglement.</p><hr><h2 id="la-suite" tabindex="-1">La suite <a class="header-anchor" href="#la-suite" aria-label="Permalink to &quot;La suite&quot;">​</a></h2><p>Dans le <strong><a href="./module-2.html">Module 2 : Comment fonctionne la température ?</a></strong>, vous utiliserez ce que vous avez appris sur les tokens pour comprendre comment le modèle <em>choisit</em> entre eux. La température contrôle la distribution de probabilité sur le vocabulaire — et vous découvrirez que ce n&#39;est pas un curseur linéaire mais une transition de phase.</p><hr><div style="background:rgba(168,85,247,0.06);border-radius:8px;padding:1rem 1.5rem;margin-top:2rem;font-size:0.9rem;color:var(--vp-c-text-2);"><p><strong>Module 1 sur 8</strong> du Kit Enseignants LLMxRay <a href="./index.html">Retour au programme</a> | <a href="./module-2.html">Suivant : Module 2 — Comment fonctionne la température ? →</a></p></div>',86)])])}const k=t(u,[["render",d]]);export{f as __pageData,k as default};
